// Development-only asset generator; the product/build consumes the checked-in ICO.
// Requires Node.js and sharp. Run with --check to detect stale generated bytes.
const fs = require("node:fs");
const path = require("node:path");
const sharp = require("sharp");

async function main() {
    const directory = path.join(__dirname, "..", "resources", "icons", "brand");
    const source = fs.readFileSync(path.join(directory, "qcat.svg"), "utf8");
    const sizes = [16, 20, 24, 32, 40, 48, 64, 128, 256];
    const images = [];
    for (const size of sizes) {
        const svg = size < 32 ? source.replace(/<g id="ear_details">.*?<\/g>/s, "") : source;
        images.push(await sharp(Buffer.from(svg), { density: 384 }).resize(size, size).png().toBuffer());
    }
    const header = Buffer.alloc(6 + 16 * sizes.length);
    header.writeUInt16LE(1, 2);
    header.writeUInt16LE(sizes.length, 4);
    let offset = header.length;
    sizes.forEach((size, index) => {
        const entry = 6 + 16 * index;
        header[entry] = size === 256 ? 0 : size;
        header[entry + 1] = size === 256 ? 0 : size;
        header.writeUInt16LE(1, entry + 4);
        header.writeUInt16LE(32, entry + 6);
        header.writeUInt32LE(images[index].length, entry + 8);
        header.writeUInt32LE(offset, entry + 12);
        offset += images[index].length;
    });
    const expected = Buffer.concat([header, ...images]);
    const output = path.join(directory, "quickclash.ico");
    if (process.argv.includes("--check")) {
        if (!fs.existsSync(output) || !fs.readFileSync(output).equals(expected)) {
            throw new Error("Brand ICO is stale; run scripts/build_brand_icon.cjs.");
        }
        console.log("Brand SVG/ICO consistency passed.");
    } else {
        fs.writeFileSync(output, expected);
        console.log("Built quickclash.ico: " + sizes.join("/") + " px; " + expected.length + " bytes.");
    }
}
main().catch(error => { console.error(error.message); process.exitCode = 1; });
